function Toggle({label,text,value,onChange}:{label:string;text:string;value:boolean;onChange:(v:boolean)=>void}){return <button className="toggleRow" onClick={()=>onChange(!value)}><div><b>{label}</b><small>{text}</small></div><i className={value?'on':''}><em/></i></button>}
function Empty({title,text,action,onClick}:{title:string;text:string;action?:string;onClick?:()=>void}){return <div className="empty"><i>‚óá</i><h3>{title}</h3><p>{text}</p>{action&&<button className="primary" onClick={onClick}>{action}</button>}</div>}
function FpsMonitor(){
  const [metrics,setMetrics]=useState({fps:0,p50:0,p95:0,p99:0,worst:0,dropped:0,long50:0,long100:0});
  const ref=useRef({last:performance.now(),frames:[] as number[],raf:0,long50:0,long100:0,lastPublish:0});
  useEffect(()=>{
    let observer:PerformanceObserver|undefined;
    try{observer=new PerformanceObserver(list=>{for(const entry of list.getEntries()){if(entry.duration>50)ref.current.long50++;if(entry.duration>100)ref.current.long100++}});observer.observe({entryTypes:['longtask']})}catch{}
    const reset=()=>{const r=ref.current;r.last=performance.now();r.frames=[];r.long50=0;r.long100=0;r.lastPublish=performance.now();setMetrics({fps:0,p50:0,p95:0,p99:0,worst:0,dropped:0,long50:0,long100:0})};
    window.addEventListener('vyron:fps-reset',reset);
    const pct=(rows:number[],p:number)=>rows.length?rows[Math.min(rows.length-1,Math.floor((rows.length-1)*p))]:0;
    const loop=(t:number)=>{
      const r=ref.current,delta=t-r.last;r.last=t;
      if(delta>0&&delta<1000){r.frames.push(delta);if(r.frames.length>360)r.frames.shift()}
      if(t-r.lastPublish>=700&&r.frames.length){
        const rows=[...r.frames].sort((a,b)=>a-b),avg=r.frames.reduce((a,b)=>a+b,0)/r.frames.length;
        const next={fps:Math.round(1000/avg),p50:pct(rows,.5),p95:pct(rows,.95),p99:pct(rows,.99),worst:rows[rows.length-1],dropped:r.frames.filter(x=>x>20).length/r.frames.length*100,long50:r.long50,long100:r.long100};setMetrics(next);window.dispatchEvent(new CustomEvent('vyron:fps-metrics',{detail:next}));
        r.lastPublish=t;
      }
      r.raf=requestAnimationFrame(loop);
    };
    ref.current.raf=requestAnimationFrame(loop);
    return()=>{cancelAnimationFrame(ref.current.raf);observer?.disconnect();window.removeEventListener('vyron:fps-reset',reset)};
  },[]);
  const bad=metrics.p95>30||metrics.long50>0;
  return <div className={`fps fpsDetailed ${bad?'bad':''}`}><b>{metrics.fps||'‚Ä¶'} FPS</b><span>p50 {metrics.p50.toFixed(1)} ms</span><span>p95 {metrics.p95.toFixed(1)} ms</span><span>p99 {metrics.p99.toFixed(1)} ms</span><span>worst {metrics.worst.toFixed(1)} ms</span><span>dropped {metrics.dropped.toFixed(1)}%</span><span>long &gt;50 {metrics.long50} ‚Ä¢ &gt;100 {metrics.long100}</span></div>
}
function formatUpdaterBytes(n:number){if(!n)return '‚Äî';const mb=n/1024/1024;return `${mb.toFixed(mb>=100?0:1)} MB`}
function UpdaterSidebar(){
 const current=useUpdaterRuntime(s=>s.currentVersion),latest=useUpdaterRuntime(s=>s.latestVersion),status=useUpdaterRuntime(s=>s.status),progress=useUpdaterRuntime(s=>s.progress),downloaded=useUpdaterRuntime(s=>s.downloadedBytes),total=useUpdaterRuntime(s=>s.totalBytes),errorCode=useUpdaterRuntime(s=>s.errorCode),download=useUpdaterRuntime(s=>s.download),install=useUpdaterRuntime(s=>s.installAndRestart),check=useUpdaterRuntime(s=>s.check),runtimeBlockers=useUpdaterRuntime(s=>s.blockers),jobs=useApp(s=>s.jobs),channels=useApp(s=>s.channels);
 const blockers=status==='READY_TO_INSTALL'?currentUpdaterBlockers(jobs,channels.map(x=>x.id)):runtimeBlockers;
 const available=['AVAILABLE','DOWNLOADING','VERIFYING','READY_TO_INSTALL','INSTALLING','READY_TO_RESTART','RESTARTING'].includes(status);
 const installNow=async()=>{const now=currentUpdaterBlockers(jobs,channels.map(x=>x.id));await install(now)};
 return <section className={`updaterSidebar ${available?'available':''} ${status==='ERROR'?'error':''}`} data-updater-status={status}><div className="updaterVersion"><span>VYRON {current||'‚Ä¶'}</span>{status==='UP_TO_DATE'||status==='UPDATED'?<small>‚úì –ê–∫—Ç—É–∞–ª—å–Ω–∞—è –≤–µ—Ä—Å–∏—è</small>:status==='CHECKING'?<small>–ü—Ä–æ–≤–µ—Ä–∫–∞ –æ–±–Ω–æ–≤–ª–µ–Ω–∏–π‚Ä¶</small>:null}</div>{available&&<><b>üîî –î–æ—Å—Ç—É–ø–Ω–æ –æ–±–Ω–æ–≤–ª–µ–Ω–∏–µ {latest}</b>{status==='AVAILABLE'&&<button className="updaterPrimary" onClick={()=>void download()}>–û–ë–ù–û–í–ò–¢–¨</button>}{(status==='DOWNLOADING'||status==='VERIFYING')&&<><small>{status==='DOWNLOADING'?`‚¨á ${progress.toFixed(0)}%`:'–ü—Ä–æ–≤–µ—Ä–∫–∞ –ø–∞–∫–µ—Ç–∞‚Ä¶'} {total>0&&`‚Ä¢ ${formatUpdaterBytes(downloaded)} / ${formatUpdaterBytes(total)}`}</small><div className="updaterMiniProgress"><i style={{width:`${progress}%`}}/></div></>}{status==='READY_TO_INSTALL'&&<><small>‚úì –û–±–Ω–æ–≤–ª–µ–Ω–∏–µ –∑–∞–≥—Ä—É–∂–µ–Ω–æ –∏ –≥–æ—Ç–æ–≤–æ –∫ —É—Å—Ç–∞–Ω–æ–≤–∫–µ.</small>{blockers.length>0&&<div className="updaterBlockers">–°–Ω–∞—á–∞–ª–∞ –∑–∞–≤–µ—Ä—à–∏—Ç–µ –∑–∞–¥–∞—á–∏:<br/>{updaterBlockerText(blockers).split('\n').map(x=><span key={x}>{x}</span>)}</div>}<button className="updaterPrimary" disabled={blockers.length>0} onClick={()=>void installNow()}>–£–°–¢–ê–ù–û–í–ò–¢–¨ –ò –ü–ï–†–ï–ó–ê–ü–£–°–¢–ò–¢–¨</button></>}{status==='INSTALLING'&&<small>–£—Å—Ç–∞–Ω–æ–≤–∫–∞‚Ä¶</small>}{status==='READY_TO_RESTART'&&<small>‚úì –ì–æ—Ç–æ–≤–æ –∫ –ø–µ—Ä–µ–∑–∞–ø—É—Å–∫—É</small>}{status==='RESTARTING'&&<small>–ü–µ—Ä–µ–∑–∞–ø—É—Å–∫‚Ä¶</small>}</>}{status==='ERROR'&&<><b>–û–±–Ω–æ–≤–ª–µ–Ω–∏–µ: –æ—à–∏–±–∫–∞</b><small>{errorCode||'UPDATER_ERROR'}</small><button onClick={()=>void check({force:true})}>–ü–û–í–¢–û–†–ò–¢–¨</button></>}</section>
}
